package terminal

// Emulator is Terminal::Emulator: it consumes parser actions and maintains a
// framebuffer, including the terminal-to-host replies generated by DA/DSR.
type Emulator struct {
	fb       *Framebuffer
	dispatch *Dispatcher
	user     *UserInput
}

// NewEmulator returns an emulator with a width by height blank framebuffer.
func NewEmulator(width, height int) *Emulator {
	return &Emulator{
		fb:       NewFramebuffer(width, height),
		dispatch: NewDispatcher(),
		user:     NewUserInput(),
	}
}

// Clone returns a deep copy, as Terminal::Emulator's C++ copy constructor.
// Parser boundaries can fall inside a CSI or OSC sequence, so the dispatcher's
// collected state is copied too.
func (e *Emulator) Clone() *Emulator {
	return &Emulator{
		fb:       e.fb.Clone(),
		dispatch: e.dispatch.Clone(),
		user:     &UserInput{state: e.user.state},
	}
}

// Framebuffer returns the current framebuffer. Callers must not retain it
// across a mutating call unless they clone it first.
func (e *Emulator) Framebuffer() *Framebuffer { return e.fb }

// CloneFramebuffer returns a deep copy of the current framebuffer.
func (e *Emulator) CloneFramebuffer() *Framebuffer { return e.fb.Clone() }

// ReadOctetsToHost drains and returns the terminal-to-host reply stream.
func (e *Emulator) ReadOctetsToHost() string {
	out := e.dispatch.TerminalToHost
	e.dispatch.TerminalToHost = ""
	return out
}

// Resize resizes the framebuffer, as a remote resize instruction does.
func (e *Emulator) Resize(width, height int) { e.fb.Resize(width, height) }

// Act applies one already-decoded parser action.
func (e *Emulator) act(a action) {
	switch a.kind {
	case actionNone:
		return
	case actionPrint:
		e.print(a.ch)
	case actionExecute:
		e.dispatch.Dispatch(functionControl, a.ch, e.fb)
	case actionClear:
		e.dispatch.Clear()
	case actionCollect:
		e.dispatch.Collect(a.ch)
	case actionParam:
		e.dispatch.NewParamChar(a.ch)
	case actionCSIDispatch:
		e.dispatch.Dispatch(functionCSI, a.ch, e.fb)
	case actionEscDispatch:
		e.escDispatch(a.ch)
	case actionOSCStart:
		e.dispatch.OSCStart()
	case actionOSCPut:
		e.dispatch.OSCPut(a.ch)
	case actionOSCEnd:
		e.dispatch.OSCDispatch(e.fb)
	}
}

func (e *Emulator) escDispatch(ch rune) {
	// Handle the 7-bit ESC encoding of C1 control characters.
	if e.dispatch.GetDispatchChars() == "" && ch >= 0x40 && ch <= 0x5f {
		e.dispatch.Dispatch(functionControl, ch+0x40, e.fb)
		return
	}
	e.dispatch.Dispatch(functionEscape, ch, e.fb)
}

// print is Emulator::print.
func (e *Emulator) print(ch rune) {
	width := RuneWidth(ch)
	fb := e.fb

	switch width {
	case 1, 2: // normal or wide character
		if fb.DS.AutoWrapMode && fb.DS.NextPrintWillWrap {
			fb.Row(-1).SetWrap(true)
			fb.DS.MoveCol(0, false, false)
			fb.MoveRowsAutoscroll(1)
		} else if fb.DS.AutoWrapMode && width == 2 &&
			fb.DS.cursorCol == fb.DS.width-1 {
			// Wrap a two-cell character with no room, even without the
			// will-wrap flag.
			fb.ResetCell(fb.Cell(-1, -1))
			fb.Row(-1).SetWrap(false)
			fb.DS.MoveCol(0, false, false)
			fb.MoveRowsAutoscroll(1)
		}

		if fb.DS.InsertMode {
			for i := 0; i < width; i++ {
				fb.InsertCell(fb.DS.cursorRow, fb.DS.cursorCol)
			}
		}

		cell := fb.Cell(-1, -1)
		fb.ResetCell(cell)
		cell.Append(ch)
		cell.Wide = width == 2
		fb.ApplyRenditionsToCell(cell)

		if width == 2 && fb.DS.cursorCol+1 < fb.DS.width {
			// Erase the overlapped cell.
			fb.ResetCell(fb.Cell(fb.DS.cursorRow, fb.DS.cursorCol+1))
		}

		fb.DS.MoveCol(width, true, true)

	case 0: // combining character
		combiningCell := fb.CombiningCell()
		if combiningCell == nil {
			break // character is now offscreen
		}
		if combiningCell.Empty() {
			// The cell starts with a combining character.
			combiningCell.Fallback = true
			fb.DS.MoveCol(1, true, true)
		}
		if !combiningCell.Full() {
			combiningCell.Append(ch)
		}

	case -1: // unprintable character
	}
}
